import java.util.*;

public class Main {
    int maxScore(int[] cardPoints, int k) {
        int n = cardPoints.length;
        int best = 0;
        for (int takenFromFront = 0; takenFromFront <= k; takenFromFront++) {
            int takenFromBack = k - takenFromFront;
            int frontSum = 0;
            for (int i = 0; i < takenFromFront; i++) frontSum += cardPoints[i];
            int backSum = 0;
            for (int i = n - takenFromBack; i < n; i++) backSum += cardPoints[i];
            best = Math.max(best, frontSum + backSum);
        }
        return best;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.maxScore(new int[]{1, 2, 3, 4, 5, 6, 1}, 3));
    }
}

