import java.util.*;

public class Main {
    int maxScore(int[] cardPoints, int k) {
        int n = cardPoints.length;
        int windowSize = n - k;                                                   // size of the single leftover middle block
        int total = 0;
        for (int c : cardPoints) total += c;
        if (windowSize == 0) return total;                                        // taking every single card, nothing is left behind
        int windowSum = 0;
        for (int i = 0; i < windowSize; i++) windowSum += cardPoints[i];
        int minWindow = windowSum;
        for (int right = windowSize; right < n; right++) {
            windowSum += cardPoints[right] - cardPoints[right - windowSize];       // slide the leftover block forward by one
            minWindow = Math.min(minWindow, windowSum);
        }
        return total - minWindow;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.maxScore(new int[]{1, 2, 3, 4, 5, 6, 1}, 3));
    }
}

